const DRAFT_KEY = 'licycolba_draft_solicitud';

// Selector de hora uniforme (24h) para el editor de horarios — dos <select>
// (hora 00-23, minuto 00-59) en vez de <input type="time">, cuyo formato de
// presentación (12h "a. m."/"p. m." vs 24h) depende del navegador/SO y no
// se puede forzar de forma confiable. Con estos selects siempre se ve
// "14:00", nunca "02:00 p. m.", coherente con el resto de la plataforma.
const HORAS_24=Array.from({length:24},(_,i)=>String(i).padStart(2,'0'));
const MINUTOS_60=Array.from({length:60},(_,i)=>String(i).padStart(2,'0'));

// ── Presentación de programaciones — ETAPA FINAL D/E §13, extendida por
// el ajuste "CREAR UN MODO EXPLÍCITO DE CAPTURA". Funciones puras movidas
// a horarios/formato-distribucion.ts (probadas ahí, sin React/jsdom) —
// aquí solo se re-exportan con el sufijo MO ya usado en el resto de este
// archivo, para no tocar cada punto de uso.
const describirDiasDistribucionMO=describirDiasDistribucion;
const formatearResumenHorarioMO=formatearResumenHorarioDistribucion;
const formatearDescansoAplicadoMO=formatearDescansoAplicadoDistribucion;
// Ajuste "AJUSTA EL RESULTADO... TURNO (DIURNO, NOCTURNO, POR HORAS)...
// 24H, 12H" — clasificación de TURNO puramente por horario de reloj
// (nunca por el tipo de cobertura/interpretación de turnos, que responde
// a otra pregunta: cuántos días cubre, no a qué hora) — 24 HORAS/12 HORAS
// cuando la duración del bloque coincide exactamente con esas jornadas
// clásicas; en cualquier otro caso, DIURNO/NOCTURNO según la hora de
// inicio del bloque (18:00-06:00 se considera nocturno).
function derivarTurnoTipoMO(dist:DistribucionHorarioConfigurada|undefined):string{
  if(!dist)return '—';
  if(dist.tipoCapturaHorario==='TOTAL_SEMANAL')return 'POR HORAS';
  const bloque=dist.bloques[0];
  if(!bloque)return '—';
  const [hIni,mIni]=bloque.inicio.split(':').map(Number);
  const [hFin,mFin]=bloque.fin.split(':').map(Number);
  let duracionMin=(hFin*60+mFin)-(hIni*60+mIni);
  if(duracionMin<=0)duracionMin+=24*60;
  const horas=Math.round(duracionMin/60);
  if(horas>=23)return '24 HORAS';
  if(horas===12)return '12 HORAS';
  const nocturno=hIni>=18||hIni<6;
  return nocturno?'NOCTURNO':'DIURNO';
}
// Ajuste "CORRECCIÓN UX MÍNIMA — CAMPO DIRECTO DE HORAS SEMANALES" —
// `calcularTotalSemanalCargo` (horarios/distribucion-semanal.ts) es
// puramente HORARIO_DETALLADO (bloques) — las distribuciones TOTAL_SEMANAL
// no tienen bloques, así que su total se suma aparte desde
// `horasSemanalesManual` (dato autoritativo) sin tocar la función
// compartida. Único punto para las 3 pantallas que muestran "horas
// semanales" de un cargo (modal de horario + tabla principal de Mano de
// Obra/Turnantes) — nunca duplicado inline.
function calcularTotalSemanalCargoConTotalSemanal(distribuciones:DistribucionHorarioConfigurada[]):number{
  return calcularTotalSemanalCargo(distribuciones)
    +distribuciones.filter(d=>d.tipoCapturaHorario==='TOTAL_SEMANAL').reduce((s,d)=>s+Math.round((d.horasSemanalesManual||0)*60),0);
}

/* =========================================================
   Helpers globales de normalización segura
========================================================= */

function safeString(value: unknown, fallback = ''): string {
  if (value === null || value === undefined) return fallback;
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') return String(value);
  return fallback;
}

function safeNumber(value: unknown, fallback = 0): number {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const cleaned = value.replace(/[^\d.-]/g, '');
    const parsed = Number(cleaned);
    return Number.isFinite(parsed) ? parsed : fallback;
  }
  return fallback;
}

function safeRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function safeArray<T = unknown>(value: unknown): T[] {
  return Array.isArray(value) ? (value as T[]) : [];
}

function useDebounce<T>(value: T, delay = 300): T {
  const [debounced, setDebounced] = React.useState<T>(value);
  React.useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

function getRecordValue(record: Record<string, unknown> | null | undefined, key: string, fallback: unknown = ''): unknown {
  if (!record) return fallback;
  return Object.prototype.hasOwnProperty.call(record, key) ? record[key] : fallback;
}

function getWindowXlsx(): XlsxLike | undefined {
  if (typeof window === 'undefined') return undefined;
  return (window as Window & { XLSX?: XlsxLike }).XLSX;
}

