const estadoModalColor=(e:string)=>{const s=e.toLowerCase();if(s.includes('convocatoria')||s.includes('publicado')||s.includes('abierto')||s.includes('vigente'))return{bg:'#E8F5E9',color:'#1B5E20',dot:'#2E7D32'};if(s.includes('adjudicado'))return{bg:'#E3F2FD',color:'#0D47A1',dot:'#1565C0'};if(s.includes('cerrado')||s.includes('vencido'))return{bg:'#EAF2FB',color:'#1E5799',dot:'#2E7BC4'};if(s.includes('cancelado')||s.includes('desierto'))return{bg:'#FFEBEE',color:'#B71C1C',dot:'#C62828'};if(s.includes('evaluac')||s.includes('selecc'))return{bg:'#FFF8E1',color:'#E65100',dot:'#EF6C00'};return{bg:'#F1F5F9',color:'#475569',dot:'#94A3B8'};};
const perfilColor=(p:string)=>{const s=p.toLowerCase();if(s.includes('aseo'))return{bg:'#e8edf5',color:'#0d2d5e',label:'Aseocolba'};if(s.includes('vigi'))return{bg:'#fde8eb',color:'#c8102e',label:'Vigicolba'};if(s.includes('tempo'))return{bg:'#e3eef8',color:'#1a5ea8',label:'Tempocolba'};return{bg:'#F1F5F9',color:'#475569',label:p.charAt(0).toUpperCase()+p.slice(1)};};
// Ajuste "FILTRO DE EMPRESA EN DOTACIÓN/EPP DEBE SER AUTOMÁTICO" — código
// corto que las APIs externas de Dotación/EPP (aseo/tempo/vigi) esperan,
// derivado EXCLUSIVAMENTE del perfil/empresa del proceso actual (mismo
// criterio de coincidencia de texto que `perfilColor`, para que el badge
// visible y el filtro real nunca puedan divergir). `null` significa "el
// proceso no tiene una empresa reconocible" — nunca un valor por defecto;
// quien lo consuma debe bloquear la consulta en ese caso, nunca consultar
// sin filtro ni caer a 'aseo'.
type CodigoEmpresaCatalogoDotEpp='aseo'|'tempo'|'vigi';
const derivarCodigoEmpresaCatalogoDotEpp=(perfil:string|null|undefined):CodigoEmpresaCatalogoDotEpp|null=>{
  const s=(perfil||'').toLowerCase();
  if(s.includes('aseo'))return'aseo';
  if(s.includes('vigi'))return'vigi';
  if(s.includes('tempo'))return'tempo';
  return null;
};
// Ajuste "APLICAR LA MISMA LÓGICA DE EMPRESA/PERFIL EN INSUMOS" — Insumos
// reutiliza EXACTAMENTE `derivarCodigoEmpresaCatalogoDotEpp` (mismo código
// corto aseo/tempo/vigi, mismo contrato con /api/insumos-ext, confirmado
// en su ruta) — nunca un mapeo paralelo. Lo único propio de Insumos es la
// ETIQUETA visible: el usuario pidió el nombre oficial completo en
// mayúsculas (ASEOCOLBA/TEMPOCOLBA/VIGICOLBA), distinto del "Aseocolba"
// (Title Case) que ya usa el badge de Dotación/EPP/encabezado del
// proceso — nunca se cambia el código que viaja a la API, solo la
// etiqueta mostrada.
const ETIQUETA_EMPRESA_CATALOGO_INS:Record<CodigoEmpresaCatalogoDotEpp,string>={aseo:'ASEOCOLBA',tempo:'TEMPOCOLBA',vigi:'VIGICOLBA'};
// Ajuste "REGLA REAL DE IVA/A.I.U." — etiqueta visible por régimen,
// reutilizada donde se muestre `regimenIVA` (nunca un texto libre
// distinto en cada lugar que lo despliegue).
const ETIQUETA_REGIMEN_IVA:Record<RegimenIVA,string>={
  ASEO_CAFETERIA_ESPECIAL:'Aseo y Cafetería',
  VIGILANCIA_ESPECIAL:'Vigilancia',
  SERVICIOS_TEMPORALES_ESPECIAL:'Personal en misión / Servicios temporales',
  IVA_PLENO:'IVA pleno',
  REQUIERE_REVISION:'Requiere revisión (sin clasificar)',
};
// Ajuste "ACA HACER LO MISMO QUE SE HIZO ANTERIORMENTE" — Impuestos (matriz
// ICA) reutiliza el MISMO criterio de coincidencia de texto que
// `perfilColor`/`derivarCodigoEmpresaCatalogoDotEpp` (nunca un mapeo
// paralelo), pero devuelve directamente el enum `EmpresaIca` — a
// diferencia de Dotación/EPP/Insumos, Impuestos SÍ reconoce 'transcolba'
// (EmpresaIca incluye TRANSCOLBA). '' = el proceso no tiene una empresa
// reconocible — nunca se fuerza un default arbitrario en ese caso.
const derivarEmpresaIcaDeProceso=(perfil:string|null|undefined):EmpresaIca|''=>{
  const s=(perfil||'').toLowerCase();
  if(s.includes('aseo'))return'ASEOCOLBA';
  if(s.includes('vigi'))return'VIGICOLBA';
  if(s.includes('tempo'))return'TEMPOCOLBA';
  if(s.includes('trans'))return'TRANSCOLBA';
  return'';
};
const estadoSolicitudColor=(e:string)=>{
  const s=(e||'').toLowerCase();
  if(s.includes('selección de proceso')||s.includes('seleccion de proceso')) return{bg:'#f1f5f9',color:'#475569'};
  if(s.includes('revision comercial')||s.includes('revisión comercial'))     return{bg:'#eff6ff',color:'#1e5799'};
  if(s.includes('asignado para revision')||s.includes('asignado para revisión')) return{bg:'#dbeafe',color:'#1d4ed8'};
  if(s.includes('revision finalizada')||s.includes('revisión finalizada'))   return{bg:'#f0fdf4',color:'#15803d'};
  if(s.includes('decision')||s.includes('decisión'))                         return{bg:'#faf5ff',color:'#7c3aed'};
  if(s.includes('no participar'))                                             return{bg:'#fef2f2',color:'#dc2626'};
  if(s.includes('asignado para elaboraci'))                                   return{bg:'#fff7ed',color:'#dc2626'};
  if(s.includes('elaboraci'))                                                 return{bg:'#fef9c3',color:'#854d0e'};
  if(s.includes('presentad'))                                                 return{bg:'#f0fdf4',color:'#166534'};
  if(s.includes('evaluaci'))                                                  return{bg:'#E8F5E9',color:'#15803d'};
  if(s.includes('adjudic'))                                                   return{bg:'#E3F2FD',color:'#0D47A1'};
  if(s.includes('no adjudic')||s.includes('desierto')||s.includes('cancelad')) return{bg:'#FFEBEE',color:'#B71C1C'};
  if(s.includes('cerrad'))                                                    return{bg:'#F1F5F9',color:'#475569'};
  if(s.includes('abierta')||s.includes('revision'))                           return{bg:'#e0f2fe',color:'#0369a1'};
  return{bg:'#FFF8E1',color:'#E65100'};
};

