  // `filtrosLimpios`: "Limpiar filtros" jamás toca ni restablece la
  // empresa (sigue viniendo de `empresaCatalogoProceso` en cada consulta).
  const limpiarFiltrosCatalogoEpp=async()=>{
    if(selEppLimpiando)return;
    if(selEppDebounceRef.current)clearTimeout(selEppDebounceRef.current);
    selEppAbortRef.current?.abort();
    setSelEppLimpiando(true);
    const filtrosLimpios={busqueda:'',uen:UEN_INICIAL_CATALOGO_EPP,codgrp:'',pagina:1};
    setSelEppQ(filtrosLimpios.busqueda);
    setSelEppUen(filtrosLimpios.uen);
    setSelEppCodgrp(filtrosLimpios.codgrp);
    try{
      await consultarCatalogEpp(filtrosLimpios.pagina,{uen:filtrosLimpios.uen,codgrp:filtrosLimpios.codgrp,q:filtrosLimpios.busqueda});
    }finally{
      setSelEppLimpiando(false);
    }
  };
  const toggleSelEpp=(r:EquipoRow)=>setSelEppSeleccion(prev=>{
    const m=new Map(prev);const key=codigoFilaEpp(r);
    if(m.has(key))m.delete(key);else m.set(key,r);
    return m;
  });
  const toggleAllSelEppPagina=()=>setSelEppSeleccion(prev=>{
    const m=new Map(prev);
    const todosMarcados=selEppCatalog.length>0&&selEppCatalog.every(r=>m.has(codigoFilaEpp(r)));
    selEppCatalog.forEach(r=>{const key=codigoFilaEpp(r);todosMarcados?m.delete(key):m.set(key,r);});
    return m;
  });
  const agregarSeleccionadosEpp=()=>{
    // Corrección "MODAL ÚNICO DE DOTACIÓN Y EPP" §12 — un producto sin
    // valor vigente (catálogo devuelve 0/ausente) no puede almacenarse
    // como costo válido; se omite silenciosamente en vez de crear una fila
    // con costo cero disfrazada de configuración real.
    const rows:DotItemRow[]=[];
    let omitidosSinValor=0;
    selEppSeleccion.forEach(r=>{
      const vUnit=Number(pickEpp(r,'valor','precio','price','vlr','value')??0)||0;
      if(vUnit<=0){omitidosSinValor++;return;}
      const codigoGrupo=pickEpp(r,'codgrps','codgrp','codigogrupo','codgrupo','grupo','grupocodigo','coddot');
      const fUltCompra=pickEpp(r,'fecha_ultima_compra','fechaultimacompra','ultima_compra','fecha_compra');
      rows.push({id:nextCargoItemId.current++,codigo:String(pickEpp(r,'codigo','code','ref')??''),desc:String(pickEpp(r,'nombre','descripcion','description','name','des_item')??'—'),medida:String(pickEpp(r,'undmed','medida','unidad','unit','und')??'UND'),...cantidadFrecuenciaInicialEpp(r),vUnit,section:'epp' as const,origen:'catalogo' as const,codigoGrupo:codigoGrupo!==undefined?String(codigoGrupo):undefined,fechaUltimaCompra:fUltCompra!==undefined?String(fUltCompra):undefined});
    });
    if(omitidosSinValor>0)alert(`${omitidosSinValor} producto(s) sin valor vigente no se agregaron.`);
    if(!rows.length)return;
    const lineaDestino=lineasManoObraDisponiblesEfectivas.find(l=>l.id===catalogoTargetLineaId);
    const sujetoKey=lineaDestino?construirSujetoDotacionKey(lineaDestino.origen,lineaDestino.id):undefined;
    const eppGroup=dotGroupsEfectivos.find(g=>g.tipo==='epp'&&g.lineaManoObraId===catalogoTargetLineaId);
    if(eppGroup){mutarDotGroups(p=>p.map(g=>g.id===eppGroup.id?{...g,rows:[...g.rows,...rows],categoria:'EPP',sujetoKey}:g));}
    else{mutarDotGroups(p=>[...p,{id:nextCargoGroupId.current++,tipo:'epp' as const,nombre:'EPP',rows,cargoCodigo:catalogoTargetCargo||undefined,lineaManoObraId:catalogoTargetLineaId,categoria:'EPP',sujetoKey}]);}
    setShowSelEpp(false);setSelEppSeleccion(new Map());setSelEppCatalog([]);setSelEppNombre('');setSelEppQ('');setSelEppCodgrp('');setSelEppBuscado(false);setCatalogoDotEppContexto(null);
  };
    const IVA_DOTACION=1.19;
  const valorConIva=(vUnit:number)=>(vUnit||0)*IVA_DOTACION;
  const valorMesRow=(r:DotItemRow)=>Math.floor((r.cant*valorConIva(r.vUnit))/(r.frec||1));
  const dotGroupTotals=dotGroups.map(g=>g.rows.reduce((s,r)=>s+valorMesRow(r),0));
  const _dotT=dotGroups.map((g,i)=>({tipo:g.tipo,tot:dotGroupTotals[i],tieneItems:g.rows.length>0}));
  const _dotDotConItems=_dotT.filter(x=>x.tipo==='dot'&&x.tieneItems);
  const _dotEpp=_dotT.filter(x=>x.tipo==='epp');
  // Promedio solo entre los géneros que realmente tienen dotación cargada —
  // si solo hay masculina (o solo femenina), se toma ese valor tal cual, sin
  // promediarlo con el otro género vacío (que daría la mitad de lo real).
  const dotAvg=_dotDotConItems.length>0?Math.round(_dotDotConItems.reduce((s,x)=>s+x.tot,0)/_dotDotConItems.length):0;
  const eppSum=_dotEpp.reduce((s,x)=>s+x.tot,0);
  const dotPromedio=dotAvg+eppSum;
  const eppMesPorTrab=dotPromedio;
  // Corrección "fórmula por cargo/sujeto" — `eppTotal` (abajo) SOLO
  // alimenta el snapshot histórico de /api/costos-estructura (campo
  // `costoEpp`, fuera de alcance de esta corrección) — nunca el pie de la
  // pestaña EPP y Dotación ni Resultado. El total realmente mostrado en
  // pantalla (`totalDotacionEppGeneral`, más abajo) SIEMPRE suma los
  // totales YA correctos por sujeto (línea principal o turnante, cada uno
  // con su propio promedio Masculino/Femenino y su propia cantidad real
  // de trabajadores) — nunca "promedio global × n".
  const eppTotal=eppMesPorTrab*n;

  // ── CATÁLOGO DOTACIÓN (fuente: /api/dotacion-ext → grupocolba.com/service/public/api/dotacion)
  // Ajuste "FILTRO DE EMPRESA EN DOTACIÓN/EPP DEBE SER AUTOMÁTICO" — la
  // empresa YA NO es un filtro libre (antes incluía "Todos", que mezclaba
  // productos de las 3 empresas): viene fija de `empresaCatalogoProceso`
  // (derivada del proceso actual), nunca editable, nunca restablecida por
  // "Limpiar filtros". UEN/Cód. grupo SÍ siguen siendo filtros libres.
  // Ajuste (petición directa) "QUE QUEDE FIJO BAQ, PERO QUE ME PERMITA
  // SELECCIONAR BOG Y DEMAS" — BAQ es el valor inicial del selector de UEN
  // (nunca "Todos"/vacío), pero el usuario sigue pudiendo elegir BOG/MIN.
  const UEN_INICIAL_CATALOGO_DOT='BAQ';
  const [showSelDot,setShowSelDot]=useState(false);
  const selDotEmpresa:string=empresaCatalogoProceso??'';
  const [selDotUen,setSelDotUen]=useState(UEN_INICIAL_CATALOGO_DOT);
  const [selDotCodgrp,setSelDotCodgrp]=useState('');
  const [selDotSexo,setSelDotSexo]=useState<''|'F'|'M'>('');
  const [selDotCarg,setSelDotCarg]=useState(false);
  const [selDotErr,setSelDotErr]=useState('');
  const [selDotCatalog,setSelDotCatalog]=useState<EquipoRow[]>([]);
  // Ajuste "OPTIMIZAR VELOCIDAD DEL CATÁLOGO" §11/§15 — la selección se
