  const totalVariablesAdministrativas=calcularTotalVariablesAdministrativas(variablesAdmin,cantidadTrabajadoresServicio);

  // Consolidado — misma función pura reutilizada en Costos Administrativos,
  // Resumen y Resultado (nunca se reimplementa la suma en ningún otro sitio).
  const consolidadoAdmin=calcularConsolidadoCostosAdministrativos({
    totalCostosModulos,
    totalVariablesAdministrativas,
    valorMensualPolizas:polizasCalculado.valorMensual,
    valorMensualImpuestos,
  });
  // `adminTotal` se conserva como nombre (usado en Resumen/Resultado/
  // guardarCosteo) pero ahora representa el TOTAL MENSUAL ADMINISTRATIVO
  // canónico (pólizas + impuestos + variables) — nunca el modelo anterior.
  const adminTotal=consolidadoAdmin.totalMensualAdministrativo;
  // Ajuste "REDISEÑAR LA PESTAÑA INSUMOS" ETAPA 3 §13 / "ESTRUCTURA
  // DEFINITIVA DE COSTOS ADMINISTRATIVOS" §6 — total general de la
  // Estructura de Costos = totalCostosModulos + totalMensualAdministrativo,
  // EXACTAMENTE una vez cada uno (misma fórmula que `costoMensualGeneral`).
  const totalEstructuraCostos=consolidadoAdmin.costoMensualGeneral;
  // Ajuste "REDISEÑAR COMPLETAMENTE LA PESTAÑA RESULTADO" — Resultado deja
  // de ser el resumen técnico por línea y pasa a ser una TARIFA DE
  // SERVICIO comercial consolidada (`calcularTarifaServicio`, módulo
  // puro). Los 4 totales fuente son EXACTAMENTE los mismos 4 que ya
  // alimentaban Resultado antes de este ajuste (auditados uno por uno,
  // nunca reconstruidos): `tarifaMensualTotalManoObra`, `totalMensualInsumos`,
  // `maqTotal`, `adminTotal`. La vigencia reutiliza
  // `polizasNumeroMesesContrato` (misma fuente única que ya usan Pólizas/
  // Impuestos para mensualizar).
  // Ajuste "REGLA REAL DE IVA/A.I.U. — HOJA RESUMEN DEL EXCEL DE
  // REFERENCIA" (confirmado explícitamente) — `regimenIvaPropuesto` es
  // SIEMPRE una PROPUESTA automática explícita (`proponerRegimenIVA`,
  // regla interna de la empresa: Aseo/Cafetería > Vigilancia > IVA pleno
  // — nunca doctrina/interpretación libre), a partir de los nombres de
  // cargo reales del proceso.
  const conceptosServicioProceso=React.useMemo(
    ()=>[...lineasExtra.map(l=>l.nombreCargo),solicitudProceso?.perfil??''],
    [lineasExtra,solicitudProceso?.perfil],
  );
  const regimenIvaPropuesto=React.useMemo(
    ()=>proponerRegimenIVA(conceptosServicioProceso),
    [conceptosServicioProceso],
  );
  // Ajuste "CORRIGE LA CABECERA DE DETALLE DE LA TARIFA" (confirmado
  // explícitamente) — `tipoServicioClasificado` (QUÉ se vende) es un dato
  // COMPLETAMENTE SEPARADO de `regimenIvaPropuesto`/`regimenIVAEfectivo`
  // (CÓMO se liquida tributariamente); nunca se deriva uno del otro.
  // `clasificarTipoServicio` es puro y no comparte código con
  // `proponerRegimenIVA` — ver su doc en calculo-tarifa-servicio.ts.
  const tipoServicioClasificado=React.useMemo(
    ()=>clasificarTipoServicio(conceptosServicioProceso),
    [conceptosServicioProceso],
  );
  // Ajuste "CORRIGE EL FLUJO DE GESTIONAR TARIFA" §3/§5/§8 (confirmado
  // explícitamente) — el selector manual de régimen SOLO aparece cuando
  // la propuesta automática es `REQUIERE_REVISION` (cualquier usuario con
  // acceso al módulo puede resolverlo — no es "override", es la
  // determinación que la regla automática no pudo hacer) o cuando
  // `esAdminCostos` pulsa la acción explícita "Cambiar régimen"
  // (`mostrarOverrideAdminRegimen`) — un usuario normal NUNCA ve un select
  // editable para un régimen que la política interna/norma ya determinó.
  const mostrarSelectorRegimenIVA=regimenIvaPropuesto==='REQUIERE_REVISION'||(esAdminCostos&&mostrarOverrideAdminRegimen);
  // Ajuste "CORRIGE EL FLUJO DE GESTIONAR TARIFA" (confirmado
  // explícitamente) — `regimenIVAConfirmado` ya NO es "confirmación
  // manual de cualquier usuario": es el OVERRIDE ADMINISTRATIVO (§8) o la
  // resolución de un `REQUIERE_REVISION` (el único caso con intervención
  // humana). Sin ese override, el régimen EFECTIVO es SIEMPRE la
  // propuesta automática — la política interna (Aseo solo) NUNCA exige
  // una confirmación adicional para pasar a ser el régimen efectivo (§1/
  // §2). El origen NORMA/POLITICA_INTERNA/OVERRIDE_ADMIN (§4/§7) sigue
  // siendo derivable en cualquier momento — `proponerOrigenRegimenIVA(conceptosServicioProceso)`
  // para el primero, `regimenIVAConfirmado!=null` para el segundo — pero
